  `notice_period_excluded` tinyint(1) DEFAULT '0',
  `prefix_suffix_rule_enabled` tinyint(1) DEFAULT '0',
  `floating_holiday_quota` int DEFAULT '0',
  `max_team_members_on_leave_simultaneously` int DEFAULT NULL,
